  const title = data.title || '';
  const description = data.description || '';

  const text = `${title} ${description}`;

  // 기업명 매칭
  const nameMatch = nameAliases.some(alias =>
    text.includes(alias)
  );

  // 종목코드 매칭
  const tickerMatch = tickerAlias
    ? text.includes(tickerAlias)
    : false;

  // 제목에 기업명 있으면 높은 관련성
  const titleMatch = nameAliases.some(alias =>
    title.includes(alias)
  );

  // 이벤트 키워드 존재 여부
  const contextMatch = contextKeywords.some(keyword =>
    text.includes(keyword)
  );

  /*
    관련성 판단 기준

    1) 제목에 기업명 존재
