if (integrityNote) errorSummaryParts.push(integrityNote);
if (failedDetails.length) errorSummaryParts.push(failedDetails.join(' | '));
const errorSummary = errorSummaryParts.length ? errorSummaryParts.join(' || ') : null;

const runId = startedAt
  ? startedAt.replace(/[-:]/g, '').replace('T', '_').slice(0, 15)
  : finishedAt.replace(/[-:]/g, '').replace('T', '_').slice(0, 15);

return [{
  json: {
    run_id: runId,
    started_at: startedAt,
    finished_at: finishedAt,
    run_status: runStatus,
    company_total: companyTotal,
    company_completed: companyCompleted,
    article_relevant: articleRelevant,
    article_duplicate: articleDuplicate,
    article_saved: articleSaved,
    article_analysis_failed: articleAnalysisFailed,
    company_failed: companyFailed,
    error_summary: errorSummary
  }
}];

const TELEGRAM_MAX_LENGTH = 4096;
const FOOTER = 'Automated by n8n';

function line(char, count) {
  return char.repeat(count);
}

function buildHeader(dateStr) {
  return [
    '📊 DAILY MARKET BRIEF',
    dateStr,
    line('━', 10)
  ].join('\n');
}

function buildSummarySection(data) {
  return [
    'Execution Summary',
    line('─', 10),
    `Companies : ${data.company_completed} / ${data.company_total}`,
    `Relevant News : ${data.article_relevant}`,
    `New Articles : ${data.new_articles}`,
    `AI Selected : ${data.ai_selected}`,
    `Failed : ${data.failed}`
  ].join('\n');
}

function buildStateBody(data) {
  if (data.state === 'EMPTY') {
    return '이번 실행에서는 새로 저장된 기사가 없습니다.\n관련 기사는 모두 기존 저장 기사와 중복되었습니다.';
  }
  if (data.state === 'NEW_ONLY') {
    return `신규 기사 ${data.new_articles}건을 저장했습니다.\n다만 분석 기준을 통과한 기사는 없습니다.`;
  }
  return null;
}

function buildIndustryHeader(industry) {
  return `${industry.name} · ${industry.total_count}`;
}

function buildArticleBlock(article) {
  const companyLabel = `${article.company_name} (${article.ticker})`;
  const lines = [
    `■ ${companyLabel}`,
    `Priority ${article.importance} | ${article.category} | ${article.sentiment}`,
    '',
    article.title || '',
    '',
    article.ai_summary || ''
  ];
  if (article.reasoning) {
    lines.push('', '💡 Analyst Note', article.reasoning);
  }
  lines.push('', '🔗 기사 보기', article.url || '');
  return lines.join('\n');
}

function buildIndustrySection(industry) {
  const sections = [buildIndustryHeader(industry)];
  industry.articles.forEach((article, idx) => {
    sections.push('', buildArticleBlock(article));
    if (idx < industry.articles.length - 1) {
      sections.push('', line('─', 10));
    }
  });
  return sections.join('\n');
}

function buildFullMessage(data) {
  const sections = [buildHeader(data.date), '', buildSummarySection(data)];

  const stateBody = buildStateBody(data);
  if (stateBody) {
    sections.push('', stateBody);
  } else {
    for (const industry of data.industries) {
      sections.push('', buildIndustrySection(industry));
    }
  }

  sections.push('', FOOTER);
  return sections.join('\n');
}

function splitIntoChunks(fullMessage, maxLength) {
  if (fullMessage.length <= maxLength) return [fullMessage];

  const blocks = fullMessage.split('\n\n');
  const chunks = [];
  let current = '';

  for (const block of blocks) {
    const candidate = current ? `${current}\n\n${block}` : block;
    if (candidate.length > maxLength) {
      if (current) chunks.push(current);
      if (block.length > maxLength) {
        for (let i = 0; i < block.length; i += maxLength) {
          chunks.push(block.slice(i, i + maxLength));
        }
        current = '';
      } else {
        current = block;
      }
    } else {
      current = candidate;
    }
  }
  if (current) chunks.push(current);
  return chunks;
}

const data = $input.first().json;
const fullMessage = buildFullMessage(data);
const chunks = splitIntoChunks(fullMessage, TELEGRAM_MAX_LENGTH);

return chunks.map((message, idx) => ({
  json: {
    message,
    part: idx + 1,
    total_parts: chunks.length
  }
}));

function getRunSummary() {
  const summaryItems = $('Aggregate Run Stats').all();
  return summaryItems[0]?.json || {};
}

function toTimestamp(dateStr) {
  const t = new Date(dateStr).getTime();
  return Number.isNaN(t) ? 0 : t;
}

function filterThisRunArticles(articles, startedAt) {
  if (!startedAt) return articles;
  return articles.filter(a => (a.analyzed_at || '') >= startedAt);
}

function padTicker(ticker) {
  return String(ticker ?? '').padStart(6, '0');
}

function normalizeArticle(a) {
  return {
    company_name: a.company_name,
    ticker: padTicker(a.ticker),
    importance: Number(a.importance) || 0,
    category: a.category,
    sentiment: a.sentiment,
    title: a.title,
    ai_summary: a.ai_summary,
    reasoning: a.reasoning,
    url: a.url,
    published_at: a.published_at,
    industry: a.industry || '기타'
  };
}

function groupByIndustry(articles) {
  const groups = {};
  for (const a of articles) {
    if (!groups[a.industry]) groups[a.industry] = [];
    groups[a.industry].push(a);
  }
  return groups;
}

function sortArticlesWithinGroup(articles) {
  return [...articles].sort((a, b) => {
    const priorityDiff = b.importance - a.importance;
    if (priorityDiff !== 0) return priorityDiff;
    return toTimestamp(b.published_at) - toTimestamp(a.published_at);
  });
}

function sortIndustryGroups(entries) {
  return [...entries].sort((a, b) => {
    const topA = a.articles[0]?.importance || 0;
    const topB = b.articles[0]?.importance || 0;
    if (topB !== topA) return topB - topA;
    return b.articles.length - a.articles.length;
  });
}

function determineState(newArticles, aiSelected) {
  if (newArticles === 0) return 'EMPTY';
  if (aiSelected === 0) return 'NEW_ONLY';
  return 'HAS_SELECTED';
}

function formatDate(iso) {
  if (!iso) return new Date().toISOString().slice(0, 10);
  return iso.slice(0, 10);
}

const TOP_N_PER_INDUSTRY = 3;

const summary = getRunSummary();
const rawArticles = $input.all().map(it => it.json);
const thisRunArticles = filterThisRunArticles(rawArticles, summary.started_at).map(normalizeArticle);

const newArticles = summary.article_saved ?? 0;
const aiSelected = thisRunArticles.length;
const state = determineState(newArticles, aiSelected);

let industries = [];
if (state === 'HAS_SELECTED') {
  const grouped = groupByIndustry(thisRunArticles);
  const entries = Object.entries(grouped).map(([name, articles]) => ({
    name,
    articles: sortArticlesWithinGroup(articles)
  }));
  const sortedEntries = sortIndustryGroups(entries);
  industries = sortedEntries.map(e => ({
    name: e.name,
    total_count: e.articles.length,
    articles: e.articles.slice(0, TOP_N_PER_INDUSTRY)
  }));
}

return [{
  json: {
    started_at: summary.started_at,
    date: formatDate(summary.started_at),
    company_total: summary.company_total ?? 0,
    company_completed: summary.company_completed ?? 0,
    article_relevant: summary.article_relevant ?? 0,
    new_articles: newArticles,
    ai_selected: aiSelected,
    failed: summary.company_failed ?? 0,
    state,
    industries
  }
}];
